import React from 'react';

import { updateArticleAsync } from '@apps/Articles/@services/articles.service';
import { IArticle } from '@apps/Articles/@types/articles.types';
import OneArticleEdit from '@apps/Articles/components/OneArticleEdit';
import PageHeader from '@components/PageHeader';
import { AuthContext } from '@contexts/AuthContext';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';

interface IArticleEditPageProps {
  id: number;
}

const ArticleEditPage: React.FC<IArticleEditPageProps> = ({ id }) => {
  const [data, setData] = React.useState<IArticle>();

  const authContext = React.useContext(AuthContext);

  return (
    <div>
      <Breadcrumb
        data={[
          { href: '/articles', text: 'Статьи' },
          { href: `/articles/${id}`, text: data?.name ?? '...' },
          { href: `/articles/${id}/edit`, text: 'Редактирование', active: true },
        ]}
      />
      <PohContainer>
        <PageHeader title={data?.name ?? '...'}>
          {authContext.user?.id === data?.author?.id && (
            <PohButton
              size={ButtonSize.Small}
              variant={ButtonVariant.Success}
              onClick={async () => {
                const hasChanges = await updateArticleAsync({
                  id,
                  is_publish: data?.publish_at ? false : true,
                });
                if (hasChanges) {
                  setData(
                    (x) => ({ ...x, publish_at: x?.publish_at ? null : new Date() }) as IArticle,
                  );
                }
              }}
            >
              {data?.publish_at ? 'Снять с публикации' : 'Опубликовать'}
            </PohButton>
          )}
        </PageHeader>
        {data?.publish_at && (
          <small className="text-muted">Опубликовано: {data.publish_at.toLocaleString()}</small>
        )}
        <OneArticleEdit id={id} onDataReady={setData} />
      </PohContainer>
    </div>
  );
};

export default ArticleEditPage;
