import React from 'react';

import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import OneArticleBody from './OneArticleBody';
import { getOneArticleAsync, updateArticleAsync } from '../@services/articles.service';
import { IArticle } from '../@types/articles.types';

interface IOneArticleEditProps {
  id: number;
  onDataReady?: (article: IArticle) => void;
}

const OneArticleEdit = ({ id, onDataReady }: IOneArticleEditProps) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IArticle>();
  const [text, setText] = React.useState('');
  const [err, setErr] = React.useState<string | undefined>(undefined);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const d = await getOneArticleAsync(id);
        setData(d);
        setText(d.text);
        onDataReady?.(d);
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err}</PohAlert>;
  }

  if (!data) {
    return <PohAlert>No data</PohAlert>;
  }

  return (
    <article className="d-flex flex-column" style={{ gap: 12 }}>
      <PohInput
        onRealChange={async (v: string) => {
          await updateArticleAsync({ id, name: v });
          onDataReady?.({ ...data, name: v });
        }}
        defaultValue={data.name}
      />
      <PohRow>
        <PohCol sm={6}>
          <PohInput
            placeholder="Текст"
            type={InputTypes.textarea}
            onRealChange={async (v: string) => {
              await updateArticleAsync({ id, text: v });
              onDataReady?.({ ...data, text: v });
            }}
            value={text}
            onChange={setText}
            style={{ overflowY: 'auto', height: 600 }}
          />
        </PohCol>
        <PohCol sm={6}>
          <div style={{ overflowY: 'auto', maxHeight: 600 }}>
            <OneArticleBody text={text} />
          </div>
        </PohCol>
      </PohRow>
    </article>
  );
};

export default OneArticleEdit;
